import {View,Text,StyleSheet} from "react-native";
const styles=StyleSheet.create({page:{padding:24,backgroundColor:"#eef4ff"},title:{fontSize:24,fontWeight:"bold"}});
export default function App(){return <View style={styles.page}><Text style={styles.title}>Our books</Text></View>;}

import {useState} from "react";
import {View,Text,Button} from "react-native";
export default function App(){const [count,setCount]=useState(0);return <View style={{padding:24}}><Text>Books: {count}</Text><Button title="Read one" onPress={()=>setCount(count+1)}/></View>;}

import {FlatList,Text} from "react-native";
const books=[{id:"1",title:"Moon Trip"},{id:"2",title:"Garden Days"}];
export default function App(){return <FlatList data={books} keyExtractor={item=>item.id} contentContainerStyle={{padding:24}} renderItem={({item})=><Text style={{padding:12}}>{item.title}</Text>}/>;}

